ter.", "section": "OPOZORILO! > 11.1 Rezultati pomivanja in sušenja niso zadovoljivi", "page_from": 55, "page_to": 55, "pdf_url": "/files/10.pdf#page=55", "images": [], "score": 0.1636996, "dense_rank": 24, "bm25_rank": null}]}

